def keep_person_details(apps, schema_editor):
    from apps.core.crypto import blind_index

    Order = apps.get_model("crm", "Order")
    for order in Order.objects.filter(learner__isnull=False).select_related("learner").order_by("-created_at"):
        learner = order.learner
        changed = [f for f in PERSON if getattr(order, f) and not getattr(learner, f)]
        for field in changed:
            setattr(learner, field, getattr(order, field))
        if changed:
            learner.citizen_id_index = blind_index(learner.citizen_id or "")
            learner.save()


